def extract_even(t):
    if isinstance(t, tuple) and len(t) % 2 == 0:
        return t
    result = []
    for item in t:
        if isinstance(item, tuple):
            new_item = extract_even(item)
            if not isinstance(new_item, tuple) or len(new_item) % 2 != 0:
                continue
            else:
                result.append(new_item)
        elif item % 2 == 0:
            result.append(item)
    return tuple(result)

